'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Login, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './login.css'
// The shared rule sets, for the same reason as in form.tsx: this surface
// renders actions, so the file that carries the action type and the press
// gesture ships with it (GSUI-118).
import '../../../tokens/primitives.css'

// The flat install layout puts every component in one directory, so these
// specifiers have to read `./form`. In this repo each is a directory up, and
// form.ts and the rest re-export it. See hud/score.ts, which explains it first.
import { Form } from './form'
import { Field } from './field'
import { Button } from './button'

/**
 * Login: the sign-in surface, rendered. BDS-041.
 *
 * **It never performs authentication.** It makes no network call, reads no
 * cookie, writes no token and has never heard of the customer's identity
 * provider. It collects what the player typed and reports it, and everything
 * behind that is the host's: sending the code, checking the password, deciding
 * whether this person is who they say they are.
 *
 * That is not a simplification. A library that authenticated would have to know
 * which provider the customer uses, which is the thing that makes a component
 * library un-reusable.
 *
 * The identifier is reported and never stored. There is no state here holding
 * an email between renders unless the host passes one in, and nothing writes it
 * anywhere.
 *
 * Three ways in, in the order the design draws them: the identifier and the
 * primary action, then the providers, then the way past all of it. **Play as
 * guest is not a decoration.** A player who will not sign in is a player who
 * leaves, so the escape is part of the surface rather than something a host
 * remembers to add.
 */

/** One way in that is not the identifier. The host owns what pressing it does. */
export interface LoginProvider {
  /** Stable id, handed back to `onProvider`. */
  id: string
  /** What the player reads on the button. */
  label: string
  /**
   * The provider's mark, as a node. Draw it as inline SVG taking
   * `currentColor`; a colour emoji ignores every token and changes shape per
   * platform. Optional, because the label is what carries the meaning.
   */
  icon?: React.ReactNode
}

export interface LoginProps {
  /** The headline. "Sign in to play", or whatever this game calls it. */
  title?: React.ReactNode
  /** The line under it, saying what signing in gets them. */
  detail?: React.ReactNode
  /** The game or brand lockup above the headline. The host's artwork. */
  brand?: React.ReactNode
  /** What the player is asked for. `email` by default. */
  identifier?: 'email' | 'tel' | 'text'
  /** What that field is called on screen and in the reported values. */
  identifierLabel?: string
  /** Its name in the values handed to `onSubmit`. */
  identifierName?: string
  /** What the primary action says. */
  submitLabel?: React.ReactNode
  /**
   * What the player typed, handed over. The host sends the code, checks the
   * password, or does nothing at all; this component has no idea which.
   */
  onSubmit?: (values: Record<string, string>) => void
  /** The other ways in. Rendered under a divider, in the order given. */
  providers?: LoginProvider[]
  /** Which provider the player pressed. The host opens it; this never can. */
  onProvider?: (id: string) => void
  /** What the way past sign-in says. */
  guestLabel?: React.ReactNode
  /** The player chose to play without signing in. Omit it and no escape renders. */
  onGuest?: () => void
  /** The host has been asked and has not answered. Host-declared. */
  busy?: boolean
  /** Why the last attempt was refused, in the host's own words. */
  reason?: React.ReactNode
  /** Whether the identifier failed. The host's word; this validates nothing. */
  invalid?: boolean
  /** Anything the host wants between the providers and the escape. */
  children?: React.ReactNode
}

const DEFAULTS = {
  title: 'Sign in to play',
  identifierLabel: 'Email',
  identifierName: 'email',
  submitLabel: 'Continue',
  guestLabel: 'Play as guest',
  divider: 'or',
} as const

export function Login({
  title = DEFAULTS.title,
  detail,
  brand,
  identifier = 'email',
  identifierLabel = DEFAULTS.identifierLabel,
  identifierName = DEFAULTS.identifierName,
  submitLabel = DEFAULTS.submitLabel,
  onSubmit,
  providers = [],
  onProvider,
  guestLabel = DEFAULTS.guestLabel,
  onGuest,
  busy = false,
  reason,
  invalid = false,
  children,
}: LoginProps) {
  return (
    <section className="gs-login" data-gs-component="login" aria-label={typeof title === 'string' ? title : DEFAULTS.title}>
      {brand ? (
        <div className="gs-login__brand" data-gs-scope="login" data-gs-part="brand">
          {brand}
        </div>
      ) : null}

      <Form
        name="login"
        label={typeof title === 'string' ? title : DEFAULTS.title}
        title={title}
        detail={detail}
        busy={busy}
        onSubmit={(values) => onSubmit?.(values)}
        actions={
          // The drawing's primary action is the action height, not the large
          // one: 56px in a 300px card, with the field above it at 52.
          <Button type="submit" disabled={busy}>
            {submitLabel}
          </Button>
        }
      >
        <Field
          name={identifierName}
          control={identifier}
          label={identifierLabel}
          requirement="required"
          autoComplete={identifier === 'email' ? 'email' : 'username'}
          invalid={invalid}
          reason={reason}
        />
      </Form>

      {providers.length > 0 ? (
        <>
          {/* A word, not a line on its own: a rule with nothing written on it is
              decoration, and a screen reader reads nothing at all. */}
          <p className="gs-login__divider" data-gs-scope="login" data-gs-part="divider">
            <span className="gs-login__rule" aria-hidden="true" />
            <span>{DEFAULTS.divider}</span>
            <span className="gs-login__rule" aria-hidden="true" />
          </p>
          <div className="gs-login__providers">
            {providers.map((provider) => (
              <Button
                key={provider.id}
                variant="secondary"
                className="gs-login__provider"
                data-gs-scope="login"
                data-gs-part="provider"
                disabled={busy}
                onClick={() => onProvider?.(provider.id)}
              >
                {provider.icon ? (
                  <span className="gs-login__mark" aria-hidden="true">
                    {provider.icon}
                  </span>
                ) : null}
                {provider.label}
              </Button>
            ))}
          </div>
        </>
      ) : null}

      {children}

      {/* Last, and always reachable: the player who will not sign in is the one
          most likely to leave. */}
      {onGuest ? (
        <Button
          variant="tertiary"
          className="gs-login__guest"
          data-gs-scope="login"
          data-gs-part="guest"
          disabled={busy}
          onClick={() => onGuest()}
        >
          {guestLabel}
        </Button>
      ) : null}
    </section>
  )
}

/* Login. Every value comes from a token; nothing here is a literal colour.

   Specimen 4c's first card draws this surface and design/twins/4c.json
   measures ours against it: the title, the field, the primary action, the
   divider, the providers and the way past. */

.gs-login {
  display: flex;
  flex-direction: column;
  gap: var(--gs-space-4);
  font-family: var(--gs-type-body-font-family);
  color: var(--gs-color-ink);
}

/* The host's artwork, given a shape and nothing else. */
.gs-login__brand {
  display: flex;
  align-items: center;
  justify-content: center;
}

/* -- the divider ----------------------------------------------------------- */
/* A word between two rules. The drawing sets OR in the eyebrow type, 700 at
   11px with wide tracking, and draws each rule as a 2px run of the edge colour.
   The rules are real elements rather than pseudo-elements so a measurement can
   find them; they are hidden from a screen reader, which reads the word. */
.gs-login__divider {
  display: flex;
  align-items: center;
  gap: var(--gs-space-gap);
  margin: 0;
  color: var(--gs-color-muted);
  font-family: var(--gs-type-eyebrow-font-family);
  font-size: var(--gs-type-eyebrow-font-size);
  font-weight: var(--gs-type-eyebrow-font-weight);
  letter-spacing: var(--gs-type-eyebrow-letter-spacing);
  text-transform: var(--gs-type-eyebrow-text-transform, uppercase);
}

.gs-login__rule {
  flex: 1 1 auto;
  block-size: var(--gs-stroke-ui);
  background: var(--gs-color-edge);
}

/* -- the other ways in ----------------------------------------------------- */
/* Side by side while they fit, stacked when they do not: a provider name can be
   long in any language, and two of them squeezed onto one row is how a label
   ends up clipped. The drawing puts 10px between them. */
.gs-login__providers {
  display: flex;
  flex-wrap: wrap;
  gap: var(--gs-space-gap);
}

.gs-login__provider {
  flex: 1 1 9rem;
}

/* The mark and the name are one line. Both sit inside the button's own label
   span, so the gap has to come from the mark; and the name never breaks across
   two lines, because "Continue with Google" wrapping mid-word in a 9rem button
   is how a provider ends up unreadable in the one language nobody tested. */
.gs-login .gs-login__provider .gs-button__label {
  white-space: nowrap;
}

.gs-login__mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  margin-inline-end: var(--gs-space-2);
  inline-size: var(--gs-size-icon-utility);
  block-size: var(--gs-size-icon-utility);
}

/* -- the way past ---------------------------------------------------------- */
/* A ghost with an underline, centred: the tertiary treatment is the drawing's
   own, no box and no stroke, secondary ink, and it keeps the action type, the
   focus ring and the target size, because a player who will not sign in is the
   one most likely to leave. */
.gs-login .gs-login__guest {
  align-self: center;
  text-decoration: underline;
}
